#include <stdint.h>

int main(void) {
    uint32_t previous = 4294967000u;  // just before the wrap
    uint32_t current = 200;           // just after
    printf("%lu\n", (unsigned long)(current - previous));
}

unsigned long previous = 0;
const unsigned long interval = 500;

void loop() {
  if (millis() > previous + interval) {
    previous = millis();
    toggleLed();
  }
}

fix:
if (millis() - previous >= interval) {
  previous += interval;   // or = millis()
  toggleLed();
}

