int count = 0;

void loop() {
  int pressed = digitalRead(BUTTON) == LOW;
  if (pressed) {
    count++;
  }
}

fix:
static int last = 0;
int pressed = digitalRead(BUTTON) == LOW;
if (pressed && !last) {   // rising edge
  count++;
}
last = pressed;

